def repeat_missing_count(a: list[int]) -> tuple[int, int]:
    n = len(a)
    cnt = [0] * (n + 1)
    for x in a:
        cnt[x] += 1
    rep = miss = -1
    for v in range(1, n + 1):
        if cnt[v] == 2:
            rep = v
        elif cnt[v] == 0:
            miss = v
    return rep, miss

def repeat_missing_xor(a: list[int]) -> tuple[int, int]:
    n = len(a)
    xor = 0
    for v in a:
        xor ^= v
    for v in range(1, n + 1):
        xor ^= v
    bit = xor & -xor
    g0 = g1 = 0
    for v in a:
        if v & bit:
            g1 ^= v
        else:
            g0 ^= v
    for v in range(1, n + 1):
        if v & bit:
            g1 ^= v
        else:
            g0 ^= v
    return (g1, g0) if g1 in a else (g0, g1)
